reference_solution:
def closest_capped_array_value(arr, target):
 left,right=0,max(arr)
 while left<right:
  middle=(left+right)//2
  if sum(min(x,middle) for x in arr)<target:left=middle+1
  else:right=middle
 return min((left,left-1),key=lambda cap:(abs(sum(min(x,cap) for x in arr)-target),cap))

